// ResoniqTheme.swift
// Generated by hand from design/tokens.json (version 0.2). Keep the two in sync.
// Fonts: bundle "Instrument Sans" and "IBM Plex Mono" (both SIL OFL) and list them
// under UIAppFonts in Info.plist.

import SwiftUI

public extension Color {
    init(hex: UInt32) {
        self.init(
            .sRGB,
            red: Double((hex >> 16) & 0xFF) / 255,
            green: Double((hex >> 8) & 0xFF) / 255,
            blue: Double(hex & 0xFF) / 255,
            opacity: 1
        )
    }
}

