public enum ResoniqGradient {
    private static let stops: [Gradient.Stop] = [
        .init(color: ResoniqColor.indigo, location: 0),
        .init(color: ResoniqColor.teal, location: 0.55),
        .init(color: ResoniqColor.lime, location: 1),
    ]

    /// Bass at the bottom, treble at the top. For speaker portraits.
    public static let frequencyVertical = LinearGradient(stops: stops, startPoint: .bottom, endPoint: .top)

    /// Bass on the left, treble on the right. For response curves.
    public static let frequencyHorizontal = LinearGradient(stops: stops, startPoint: .leading, endPoint: .trailing)
}

public enum ResoniqFont {
    public static let sansFamily = "Instrument Sans"
    public static let monoFamily = "IBM Plex Mono"

    public static func sans(_ size: CGFloat, weight: Font.Weight = .regular, relativeTo style: Font.TextStyle = .body) -> Font {
        .custom(sansFamily, size: size, relativeTo: style).weight(weight)
    }

    public static func mono(_ size: CGFloat, weight: Font.Weight = .regular, relativeTo style: Font.TextStyle = .body) -> Font {
        .custom(monoFamily, size: size, relativeTo: style).weight(weight)
    }

    public static let display = sans(36, weight: .semibold, relativeTo: .largeTitle)
    public static let title1 = sans(34, weight: .semibold, relativeTo: .largeTitle)
    public static let title2 = sans(30, weight: .semibold, relativeTo: .title)
    public static let title3 = sans(26, weight: .semibold, relativeTo: .title2)
    public static let headline = sans(21, weight: .semibold, relativeTo: .title3)
    public static let button = sans(18, weight: .semibold, relativeTo: .headline)
    public static let bodyLarge = sans(16, relativeTo: .body)
    public static let body = sans(15, relativeTo: .body)
    public static let caption = sans(13, relativeTo: .caption)
    public static let tab = sans(12, weight: .medium, relativeTo: .caption2)
    public static let capsLabel = mono(11, relativeTo: .caption2)
    public static let readoutLarge = mono(46, weight: .medium, relativeTo: .largeTitle)
    public static let readoutMedium = mono(34, weight: .medium, relativeTo: .title)
    public static let axis = mono(11, relativeTo: .caption2)
}

