public enum ResoniqMotion {
    public static let press = Animation.spring(response: 0.2, dampingFraction: 0.7)
    public static let settle = Animation.spring(response: 0.6, dampingFraction: 0.65)
    public static let sheet = Animation.spring(response: 0.45, dampingFraction: 0.85)
    public static let pop = Animation.spring(response: 0.35, dampingFraction: 0.6)
    public static let enter = Animation.easeOut(duration: 0.5)
    public static let traceDraw = Animation.easeOut(duration: 1.6)
    public static let waiting = Animation.easeInOut(duration: 0.6).repeatForever(autoreverses: true)
    public static let pulseRing = Animation.easeOut(duration: 1.8).repeatForever(autoreverses: false)
}

/// Instrument panel: the container for one visualisation or one group of readings.
public struct ResoniqPanel: ViewModifier {
    public init() {}

    public func body(content: Content) -> some View {
        content
            .padding(ResoniqSpace.panelPadding)
            .background(ResoniqColor.panel, in: RoundedRectangle(cornerRadius: ResoniqRadius.panel, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: ResoniqRadius.panel, style: .continuous)
                    .strokeBorder(ResoniqColor.line, lineWidth: ResoniqSize.strokeHairline)
            )
    }
}

/// The one primary action on a screen.
public struct ResoniqPrimaryButtonStyle: ButtonStyle {
    public init() {}

    public func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(ResoniqFont.button)
            .foregroundStyle(ResoniqColor.onAction)
            .frame(maxWidth: .infinity, minHeight: ResoniqSize.buttonHeight)
            .background(ResoniqColor.action, in: Capsule())
            .scaleEffect(configuration.isPressed ? 0.97 : 1)
            .animation(ResoniqMotion.press, value: configuration.isPressed)
    }
}

public extension View {
    func resoniqPanel() -> some View { modifier(ResoniqPanel()) }
}
